do $$declare v jsonb;begin
 for v in select value from private.starter_recipes loop
  perform private.validate_value('recipe',v);
 end loop;
end $$;

create function private.seed_starter_recipes(h uuid,u uuid) returns void
language plpgsql security definer set search_path='' as $$
declare added int;
begin
 perform 1 from public.households where id=h for update;
 insert into public.recipes(household_id,id,value,created_by,updated_by)
 select h,id,value,u,u from private.starter_recipes
 on conflict(household_id,id) do nothing;
 get diagnostics added=row_count;
 if added>0 then
  update public.households set calendar_revision=calendar_revision+1 where id=h;
 end if;
end $$;
revoke all on function private.seed_starter_recipes(uuid,uuid) from public,anon,authenticated;
create function private.seed_new_household() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 perform private.seed_starter_recipes(new.id,new.created_by);
 return new;
end $$;
revoke all on function private.seed_new_household() from public,anon,authenticated;
create trigger household_starter_recipes after insert on public.households
for each row execute function private.seed_new_household();
do $$declare h record;begin
 for h in select id,created_by from public.households order by id loop
  perform private.seed_starter_recipes(h.id,h.created_by);
 end loop;
end $$;

-- Preserve the existing import validator and transaction. Pristine starter
-- recipes do not count as user content, but any edited/custom recipe does.
alter function public.import_local_plan(jsonb) set schema private;
revoke all on function private.import_local_plan(jsonb) from public,anon,authenticated;
create function public.import_local_plan(p_snapshot jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare u uuid:=private.verified_user(); h uuid:=private.current_household();
 old_revisions jsonb; old_calendar_revision bigint;
begin
 if h is null then raise exception 'Household membership required' using errcode='42501';end if;
 perform 1 from public.households where id=h for update;
 if private.current_household() is distinct from h then raise exception 'Membership changed' using errcode='42501';end if;
 if exists(select 1 from public.calendar_entries where household_id=h)
 or exists(select 1 from public.shopping_lists where household_id=h)
 or exists(select 1 from public.recipes r left join private.starter_recipes s on s.id=r.id
  where r.household_id=h and (s.id is null or r.value is distinct from s.value or r.revision<>0)) then
  raise exception 'Only an empty household can import local data' using errcode='22023';
 end if;
 select coalesce(jsonb_object_agg(id,revision),'{}'::jsonb) into old_revisions
 from public.recipes where household_id=h;
 select calendar_revision into old_calendar_revision from public.households where id=h;
 delete from public.recipes where household_id=h;
 perform private.import_local_plan(p_snapshot);
 perform private.seed_starter_recipes(h,u);
 -- These starters were already visible to other devices. Never reuse their
 -- concurrency tokens after replacing them during import.
 update public.recipes r set revision=(previous.value)::bigint+1
 from jsonb_each_text(old_revisions) previous
 where r.household_id=h and r.id=previous.key;
 update public.households set calendar_revision=old_calendar_revision+1 where id=h;
end $$;
revoke all on function public.import_local_plan(jsonb) from public,anon,authenticated;
grant execute on function public.import_local_plan(jsonb) to authenticated;

create or replace function public.create_invitation() returns text
language plpgsql security definer set search_path='' as $$
declare u uuid:=private.verified_user();h uuid;token text:='';bytes bytea;
 alphabet constant text:='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
begin
 select household_id into h from public.memberships where user_id=u for update;
 if h is null then raise exception 'Household membership required' using errcode='42501';end if;
 if (select count(*) from private.invitations where created_by=u and created_at>now()-interval '1 hour')>=20 then
  raise exception 'Invitation limit reached; try later' using errcode='22023';end if;
 -- 12 independent base32 characters = 60 bits of cryptographic randomness.
 bytes:=extensions.gen_random_bytes(12);
 for i in 0..11 loop token:=token||substr(alphabet,1+get_byte(bytes,i)%32,1);end loop;
 insert into private.invitations(token_hash,household_id,created_by)
 values(extensions.digest(token,'sha256'),h,u);
 return substr(token,1,4)||'-'||substr(token,5,4)||'-'||substr(token,9,4);
end $$;
create or replace function public.redeem_invitation(p_token text) returns uuid
language plpgsql security definer set search_path='' as $$
declare u uuid:=private.verified_user(); invitation private.invitations%rowtype;token text;
begin
 perform 1 from auth.users where id=u for update;
 if exists(select 1 from public.memberships where user_id=u) then
  raise exception 'Leave your current household before joining another' using errcode='22023';end if;
 if p_token is null or length(p_token)>256 then raise exception 'Invalid invitation' using errcode='22023';end if;
 token:=regexp_replace(upper(p_token),'[-[:space:]]','','g');
 if token ~ '^[A-HJ-NP-Z2-9]{12}$' then null;
 elsif btrim(p_token) ~ '^[a-fA-F0-9]{64}$' then token:=lower(btrim(p_token));
 else raise exception 'Invalid invitation' using errcode='22023';end if;
 select * into invitation from private.invitations where token_hash=extensions.digest(token,'sha256') for update;
 if not found or invitation.redeemed_at is not null or invitation.expires_at<=now()
 or not exists(select 1 from public.memberships where user_id=invitation.created_by and household_id=invitation.household_id) then
  raise exception 'Invitation is expired or unavailable' using errcode='22023';end if;
 insert into public.memberships(user_id,household_id) values(u,invitation.household_id);
 update private.invitations set redeemed_at=now(),redeemed_by=u where token_hash=invitation.token_hash;
 return invitation.household_id;
end $$;
